-- Update Customer currentaddressid after Address is loaded
-- Sets currentaddressid to the address where address.customerid = customer.id
DO $$
BEGIN
    UPDATE webshop.customer c
    SET currentaddressid = a.id
    FROM webshop.address a
    WHERE a.customerid = c.id
      AND c.currentaddressid IS NULL
      AND a.id IS NOT NULL;
    
    RAISE NOTICE 'Updated customer.currentaddressid based on address.customerid relationships';
END $$;


