/*
 * Reset Sequences
 * Set sequences to the correct values after data load
 * This ensures new inserts get the correct next ID values
 */
DO $$
BEGIN
    -- Only reset sequences if data exists
    IF EXISTS (SELECT 1 FROM webshop.address LIMIT 1) THEN
        PERFORM setval('webshop.address_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.address));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.articles LIMIT 1) THEN
        PERFORM setval('webshop.articles_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.articles));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.colors LIMIT 1) THEN
        PERFORM setval('webshop.colors_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.colors));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.customer LIMIT 1) THEN
        PERFORM setval('webshop.customer_id_seq1', (SELECT COALESCE(MAX(id), 1) FROM webshop.customer));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.labels LIMIT 1) THEN
        PERFORM setval('webshop.labels_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.labels));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop."order" LIMIT 1) THEN
        PERFORM setval('webshop.order_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop."order"));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.order_positions LIMIT 1) THEN
        PERFORM setval('webshop.order_positions_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.order_positions));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.products LIMIT 1) THEN
        PERFORM setval('webshop.products_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.products));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.sizes LIMIT 1) THEN
        PERFORM setval('webshop.sizes_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.sizes));
    END IF;
    
    IF EXISTS (SELECT 1 FROM webshop.stock LIMIT 1) THEN
        PERFORM setval('webshop.stock_id_seq', (SELECT COALESCE(MAX(id), 1) FROM webshop.stock));
    END IF;
END $$;

